    /// <summary>23:00 on day 1, just past a spawn boundary.</summary>
    public static readonly double NIGHT = (17 * Time.TICKS_PER_HOUR) + 1;

    public static double runUntil(SimState state, Func<SimState, bool> done, double max = 2000)
    {
        for (var t = 0; t < max; t++)
        {
            if (Js.T(done(state)))
            {
                return t;
            }
            Tick.tick(state);
            expect(Invariants.checkInvariants(state), DebugText.dumpText(state)).toEqual(Js.Arr([]));
        }
        throw new Exception($"condition not met after {Js.Str(max)} ticks\n{Js.Str(DebugText.dumpText(state))}\n{Js.Str(state.survivors.map((s) => s.note).join("\n"))}");
    }

    public static SimState setup(List<string> map, JsRecord<double>? jobs = null)
    {
        jobs ??= new() {  };
        var state = ScenarioMod.loadScenario(new Scenario { seed = 3, map = map });
        foreach (var s in Js.Iter(state.survivors))
        {
            s.priorities = Js.RecordFrom(JobTypes.NO_JOBS, __r0 => { Js.MergeInto(__r0, jobs); });
        }
        return state;
    }

    /// <summary>guns</summary>
    public class D001_guns
    {

        [Fact(DisplayName = "guns > a guard takes a gun over a machete, then fetches ammo for it")]
        public void T002_a_guard_takes_a_gun_over_a_machete_then_fetches_ammo_for_it()
        {
            var state = setup(["/.s..G..a"], new() { ["guard"] = 3 });
            var s = Js.NN(Js.Get(state.survivors, 0));
            runUntil(state, (_) => s.weapon != null);
            var gun = Js.NN(state.items.find((i) => i.id == s.weapon));
            expect(gun.kind).toBe("gun");
            runUntil(state, (_) => gun.wear > 0);
            expect(gun.wear).toBe(Weapons.AMMO_ROUNDS);
            expect(state.items.some((i) => i.kind == "ammo")).toBe(false);
            expect(s.note).toBe("loaded their gun");
        }

        [Fact(DisplayName = "guns > a loaded gun shoots from range (no walking up to it), using rounds")]
        public void T003_a_loaded_gun_shoots_from_range_no_walking_up_to_it_using_rou()
        {
            var state = setup(["s.........", ".........."], new() { ["guard"] = 3 });
            var s = Js.NN(Js.Get(state.survivors, 0));
            state.items.push(new() { id = "g1", kind = "gun", pos = null, carriedBy = s.id, reservedBy = null, wear = 3, tag = null });
            s.weapon = "g1";
            state.tick = Js.I(NIGHT);
            state.zombiesTonight = 0;
            Zombies.addZombie(state, Weapons.GUN_RANGE, 0, 200, "static");
            runUntil(state, (_) => state.zombies.length == 0);
            expect(s.pos.x).toBeLessThanOrEqual(1);
            expect(Js.NN(Js.Get(state.items, 0)).wear).toBe(1);
            expect(s.note).toMatch(new JsRegExp("^shot a zombie", ""));
        }

        [Fact(DisplayName = "guns > walls block a shot")]
        public void T004_walls_block_a_shot()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.#.z"] });
            expect(Work.clearShot(state.grid, new Point { x = Js.I(0), y = Js.I(0) }, new Point { x = Js.I(4), y = Js.I(0) })).toBe(false);
            expect(Work.clearShot(state.grid, new Point { x = Js.I(0), y = Js.I(0) }, new Point { x = Js.I(1), y = Js.I(0) })).toBe(true);
        }
    }

    /// <summary>noise</summary>
    public class D005_noise
    {

        [Fact(DisplayName = "noise > wakes dormant zombies within its radius, not beyond")]
        public void T006_wakes_dormant_zombies_within_its_radius_not_beyond()
        {
            var state = setup(["s" + ".".repeat(39)]);
            state.dormant = [new() { id = "d1", x = Js.I(5), y = Js.I(0) }, new() { id = "d2", x = Js.I(35), y = Js.I(0) }];
            Noise.makeNoise(state, new Point { x = Js.I(0), y = Js.I(0) }, "fighting");
            expect(state.dormant.map((d) => d.id)).toEqual(Js.Arr(["d2"]));
            expect(state.zombies).toHaveLength(1);
            Noise.makeNoise(state, new Point { x = Js.I(10), y = Js.I(0) }, "gunfire");
            expect(state.dormant).toEqual(Js.Arr([]));
            expect(Noise.NOISE["gunfire"]).toBeGreaterThan(Noise.NOISE["fighting"]);
        }

        [Fact(DisplayName = "noise > turns a herd towards it")]
        public void T007_turns_a_herd_towards_it()
        {
            var state = setup(["s" + ".".repeat(79)]);
            state.herds = [new() { id = "h1", x = Js.I(50), y = Js.I(0), to = new Point { x = Js.I(79), y = Js.I(0) }, size = 3, nextStepTick = 0, heard = false }];
            Noise.makeNoise(state, new Point { x = Js.I(30), y = Js.I(0) }, "gunfire");
            expect(Js.NN(Js.Get(state.herds, 0)).to).toEqual(Js.Obj(("x", (object?)(10)), ("y", (object?)(0))));
        }

        [Fact(DisplayName = "noise > finishing a build is noisy")]
        public void T008_finishing_a_build_is_noisy()
        {
            var state = setup(["s.+w"]);
            Js.NN(Js.Get(state.survivors, 0)).priorities = new(JobTypes.NO_JOBS) { ["build"] = 3, ["haul"] = 3 };
            state.dormant = [new() { id = "d1", x = Js.I(0), y = Js.I(0) }];
            runUntil(state, (_) => state.blueprints.length == 0, 400);
            expect(state.dormant).toEqual(Js.Arr([]));
        }
