            Point? far = null;
            for (var dy = -Towers.TOWER_SIGHT; (dy <= Towers.TOWER_SIGHT) && !Js.T(far); dy++)
            {
                for (var dx = -Towers.TOWER_SIGHT; (dx <= Towers.TOWER_SIGHT) && !Js.T(far); dx++)
