                    if (((d2 > (Sight.SIGHT_RADIUS * Sight.SIGHT_RADIUS)) && (d2 <= (JsMath.pow((Towers.TOWER_SIGHT - 1), 2)))) && !Fog.isExplored(state, s.pos.x + dx, s.pos.y + dy))
                    {
